sn_aia_tool.script:
(function(inputs) {
    var visitorGr = new GlideRecordSecure('x_aleen_snguardian_visitor');
    var qc = visitorGr.addQuery('full_name', 'CONTAINS', inputs.visitor_name);
    qc.addOrCondition('first_name', 'CONTAINS', inputs.visitor_name);
    qc.addOrCondition('last_name', 'CONTAINS', inputs.visitor_name);
    visitorGr.query();
    var visitorList = [];
    while (visitorGr.next()) {
        var visitor = {};
        visitor.full_name = visitorGr.getValue('full_name');
        visitor.email = visitorGr.getValue('email');
        visitor.sys_id = visitorGr.getValue('sys_id');
        visitorList.push(visitor);
    }
    if (visitorList.length == 0) {
        return {
            "count": 0,
            "message": "No existing visitor with given full name"
        };
    } else {
        return {
            "count": visitorList.length,
            "visitorList": visitorList
        };
    }
})(inputs);
